    columns = []
    while tokens and tokens[0].type != TokenType.OPERATOR and tokens[0].value != ')':
        columns.append(_consume_token(tokens, TokenType.IDENTIFIER).value)
        if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ',':
            _consume_token(tokens, TokenType.OPERATOR)
    return columns

def _parse_values_list(tokens):
    values = []
    while tokens and tokens[0].type != TokenType.OPERATOR and tokens[0].value != ')':
        token = _consume_token(tokens, tokens[0].type)
        if token.type == TokenType.INTEGER:
            values.append(int(token.value))
        elif token.type == TokenType.STRING:
            values.append(str(token.value))
        elif token.type == TokenType.KEYWORD and token.value == 'TRUE':
            values.append(bool(True))
        elif token.type == TokenType.KEYWORD and token.value == 'FALSE':
            values.append(bool(False))
        elif token.type == TokenType.KEYWORD and token.value == 'NULL':
            values.append(None)
        else:
            raise SQLSyntaxError(f"Unexpected token {token.value}")
        if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ',':
            _consume_token(tokens, TokenType.OPERATOR)
    return tuple(values)

